// Préparer données finales pour Supabase
const mergedData = $('🔗 Merge Data').first().json;
const message = $('🟢 GPT-4: Message').first().json.output;
const enriched = $('🟠 LLAMA: Enrichir').first().json.output;

return [{
  json: {
    // Données de base
    name: mergedData.name,
    position: mergedData.position,
    company: mergedData.company,
    linkedin_url: mergedData.linkedin_url,

    // Qualification Claude
    score: mergedData.score,
    priority: mergedData.priority,
    analysis: mergedData.analysis,
    approach_angle: mergedData.approachAngle,
    signals: mergedData.signals,

    // Message GPT-4
    personalized_message: message,

    // Enrichissement Llama
    tags: enriched.tags || [],
    best_channel: enriched.bestChannel || 'linkedin',
    conversion_probability: enriched.conversionProbability || 0,
    follow_up_sequence: enriched.followUpSequence || {},

    // Métadonnées
    status: 'ready_to_send',
    qualified_at: mergedData.qualifiedAt,
    created_at: new Date().toISOString(),

    // LLMs utilisés
    llms_used: ['claude-sonnet-4', 'gpt-4o', 'llama3-8b']
  }
}];

